export async function loadRoleHeaderData(roleId: string, officeId: number) {
  const rolCausa = await prisma.rolCausa.findFirst({
    where: {
      id: roleId,
      officeId,
    },
    include: {
      tribunal: {
        select: {
          id: true,
          nombre: true,
          direccion: true,
          comuna: true,
        },
      },
    },
  })

  if (!rolCausa) {
    return null
